export default function plan({ values, sheet }) {
  if (!Array.isArray(values) || !values.length) return { rows: [] };
  const h = values[0],
    p = h.indexOf("Person Info"),
    u = h.indexOf("Linkedin URL");
  if (p < 0 || u < 0 || h.lastIndexOf("Person Info") !== p || h.lastIndexOf("Linkedin URL") !== u)
    throw Error("Sheet requires unique Person Info and Linkedin URL headers");
  let n = u + 1,
    col = "";
  while (n) {
    n--;
    col = String.fromCharCode(65 + (n % 26)) + col;
    n = Math.floor(n / 26);
  }
  const tab = "'" + sheet.replaceAll("'", "''") + "'";
  return {
    rows: values
      .slice(1)
      .map((r, i) => ({ person: String(r[p] ?? ""), range: `${tab}!${col}${i + 2}` }))
      .filter((x) => x.person.trim()),
  };
}

