export default function next({ rows, previous }) {
  const index = (previous?.index ?? -1) + 1;
  if (index >= rows.length)
    return {
      state: { index },
      more: false,
      person: "",
      range: "A1",
      url: "https://www.google.com/",
    };
  const r = rows[index];
  return {
    state: { index },
    more: true,
    person: r.person,
    range: r.range,
    url: "https://www.google.com/search?q=" + encodeURIComponent(r.person),
  };
}

