export default function session({ body }) {
  const x = body?.data;
  if (!x || typeof x.id !== "string" || !/^[-a-z0-9]+$/i.test(x.id) || body.errors?.length)
    throw Error("Invalid Airtop session");
  const base = "https://api.airtop.ai/api/v1/sessions/" + encodeURIComponent(x.id);
  if (!["initializing", "running", "active"].includes(x.status))
    throw Error("Invalid Airtop session state");
  return {
    windowUrl: base + "/windows",
    terminateUrl: base,
    ready: x.status === "running" || x.status === "active",
  };
}

