export default function poll({ body, previous, sessionUrl }) {
  const count = (previous?.sessionUrl === sessionUrl ? previous.count : 0) + 1;
  if (body?.errors?.length || !["initializing", "running", "active"].includes(body?.data?.status))
    throw Error("Invalid Airtop session status");
  if (count >= 60 && body.data.status === "initializing")
    throw Error("Airtop session did not become ready");
  return { state: { count, sessionUrl }, ready: body.data.status !== "initializing" };
}

