export default function query({ body, terminateUrl, person }) {
  const id = body?.data?.windowId;
  if (typeof id !== "string" || !/^[-a-z0-9]+$/i.test(id) || body.errors?.length)
    throw Error("Invalid Airtop window");
  return {
    url: terminateUrl + "/windows/" + encodeURIComponent(id) + "/page-query",
    query: {
      prompt: `This is Google Search results. the first results should be the Linkedin Page of ${person}\nReturn the Linkedin URL and nothing else.\nIf you cannot find the Linkedin URL, return an empty string.\nA valid Linkedin profile URL starts with "https://www.linkedin.com/in/"`,
    },
  };
}

