export default function result({ body }) {
  if (body?.errors?.length || typeof body?.data?.modelResponse !== "string")
    throw Error("Invalid Airtop response");
  const s = body.data.modelResponse.trim();
  if (s && !/^https:\/\/www\.linkedin\.com\/in\/[^\s]+$/i.test(s))
    throw Error("Airtop did not return a LinkedIn profile URL");
  return { values: [[s]] };
}
